            dels[(rp,l)] += 1; rp+=l
        elif op==4: soft+=1; q+=l
        elif op==3: rp+=l
print('insertions >=5')
for k,n in ins.most_common():
    if n>=5: print(k,n)
print('deletions >=5')
for k,n in dels.most_common():
    if n>=5: print(k,n)
print('softclips',soft)
